// The almanac's events of 1907, the epilogue's year (Core/Almanac.cs): dated, month by month, and the year's everyday
// talk after them (month 0). The shape is AlmanacData1899A.cs's. In 1907's lines no Philippines, bicycle, Klondike or
// century turning (the harnesses' rule: those are 1899's words).
namespace EnrageWestworld.Core
{
    public static partial class Almanac
    {
        private static readonly AlmanacEvent[] Events1907 =
        {
            // ---- January 1907 ----------------------------------------------------------------------------------
            E("purefood", 1907, 1, 2, null, 2, "law", "THE PURE FOOD LAW IN FORCE",
              "From New Year's Day the Pure Food and Drugs Act is law, and every bottle of medicine must say on its label what is in it, opium and alcohol included.",
              "The pure food law's in. The medicine man has to print what's in the bottle. Peruna was mostly whiskey.",
              "Pure food law. The label has to tell the truth from today. The tonic men print it in very small letters."),
            E("kingston", 1907, 1, 16, "world", 2, "disaster", "KINGSTON SHAKEN DOWN",
              "An earthquake has wrecked Kingston, Jamaica, and the fires after it; the dead are counted by the hundred and the English are sending ships.",
              "Earthquake flattened Kingston in Jamaica. Hundreds dead, then the fire. Like San Francisco, but smaller.",
              "Jamaica's capital is down, shaken flat. The earth's been restless ever since Frisco."),
            E("thawtrial", 1907, 1, 24, null, 3, "crime", "THE THAW TRIAL OPENS",
              "Harry Thaw, who shot the architect Stanford White on a roof garden over his wife, is on trial for his life in New York, and the papers print every word.",
              "The Thaw trial's begun. The millionaire who shot the architect over a chorus girl. Every word's in the paper.",
              "Harry Thaw's on trial. His mother's spent a million on lawyers. A poor man would've hanged by now.",
              "Everybody's reading the Thaw trial. The preacher preached against it, then asked me how it came out."),
            E("tillmanact", 1907, 1, 28, null, 1, "law", "NO MORE CORPORATION MONEY FOR CAMPAIGNS",
              "Congress has made it a crime for a corporation to give money to a candidate for federal office, after the insurance scandals showed where the money went.",
              "It's a crime now for a company to pay for an election. The railroads will find another way by Tuesday.",
              "No corporation money in politics, says the new law. I'll believe it when Hanna's ghost stops laughing."),
            // ---- February 1907 ---------------------------------------------------------------------------------
            E("nesbittestifies", 1907, 2, 8, null, 2, "crime", "MRS. THAW TELLS HER STORY",
              "Evelyn Nesbit Thaw took the stand in her husband's defense and told the court what the architect did to her at sixteen, and the women were sent from the room.",
              "Thaw's wife testified, the girl from the chorus. What she said, they sent the women out of the room for.",
              "Evelyn Thaw on the stand. Sixteen when White got hold of her, she says. Now the whole country's a jury."),
            E("larchmont", 1907, 2, 13, null, 2, "disaster", "THE LARCHMONT SUNK IN THE SOUND",
              "The steamer Larchmont was cut down by a schooner in Long Island Sound on a February night, and above a hundred drowned or froze on the rafts.",
              "A steamer went down in Long Island Sound in the night, the Larchmont. Folks froze on the rafts before morning.",
              "The Larchmont, cut in two by a schooner. The ones who got off froze to death on the water. God help them."),
            E("immigrationact", 1907, 2, 21, null, 2, "law", "A NEW IMMIGRATION LAW",
              "The new immigration act raises the head tax to four dollars, turns back more of the sick, and lets the President stop the Japanese who come by way of Hawaii.",
              "New law on immigrants. Four dollars a head to land and the sick turned back. A million came last year.",
              "They're tightening the gate. The Japanese kept out by the back door, the head tax up at the front."),
            E("gentlemensagreement", 1907, 2, 25, "west", 2, "politics", "ROOSEVELT AND THE MIKADO SETTLE THE SCHOOL QUESTION",
              "The President has made San Francisco take the Japanese children back into its schools, and Japan in turn will keep its laborers at home.",
              "Roosevelt made Frisco put the Japanese boys back in school, and Japan keeps its men home. A gentlemen's deal.",
              "The Frisco school fight's over. No more Japanese come, and California's not happy, and Japan's not either."),
            // ---- March 1907 ------------------------------------------------------------------------------------
            E("midnightforests", 1907, 3, 5, "west", 3, "west", "SIXTEEN MILLION ACRES MADE FOREST RESERVE IN A NIGHT",
              "Before signing the bill that takes the power from him, the President proclaimed sixteen million acres of the West forest reserves, and the stockmen are beside themselves.",
              "Roosevelt locked up sixteen million acres of forest before Congress could stop him. The stockmen are cursing.",
              "The midnight forests, the paper calls them. My father's old range is government timber now, with a ranger.",
              "Half the mountains are forest reserve as of this week. You'll pay to graze them, and ask a ranger where."),
            E("grafttrials", 1907, 3, 10, "west", 1, "politics", "SAN FRANCISCO TRIES ITS OWN GOVERNMENT",
              "Boss Ruef and Mayor Schmitz of San Francisco are under indictment for selling the city to the railways and the restaurants, and the trials go on among the ruins.",
              "They've indicted the mayor of San Francisco and his boss. Took money from everybody with a franchise.",
              "The Frisco graft trials. Mayor, boss and half the supervisors. They sold the city twice before the quake."),
            E("marchpanic", 1907, 3, 15, null, 2, "money", "THE STOCKS BREAK HARD",
              "Stocks fell on Wall Street as they have not since 1901, the rich men's panic the papers call it, and the big names lost millions in a day.",
              "The stocks broke in New York. Millions gone in an afternoon. Rich men's money. It'll be ours next.",
              "A panic on the stock exchange. They say it's only the rich who lost. The rich don't lose; they pass it on."),
            // ---- April 1907 ------------------------------------------------------------------------------------
            E("thawhung", 1907, 4, 13, null, 2, "crime", "THE THAW JURY CANNOT AGREE",
              "After forty-seven hours the Thaw jury came back unable to agree, seven for murder and five for insanity, and Thaw goes back to the Tombs to wait.",
              "The Thaw jury hung. Seven for hanging, five for crazy. Three months of it, and they'll do it all again.",
              "No verdict for Thaw. His mother's money bought a hung jury. A second trial, and more of the chorus girl."),
            E("ellisrecord", 1907, 4, 18, null, 1, "life", "THE BIGGEST DAY ELLIS ISLAND EVER SAW",
              "Nearly twelve thousand immigrants were landed at Ellis Island in one day, and the year will pass a million and a quarter.",
              "Twelve thousand landed at New York in one day. Twelve thousand. More than this whole county.",
              "A million and a quarter coming in this year. The steamship men sell tickets in every village in Italy."),
            E("jamestown", 1907, 4, 27, null, 1, "life", "THE JAMESTOWN EXPOSITION OPENS",
              "The President opened the Jamestown Exposition at Hampton Roads, three hundred years since the first English landing, with the navies of the world in the harbor.",
              "There's a fair at Jamestown for three hundred years of Virginia. Warships from every country in the harbor.",
              "The Jamestown exposition. The paper says it's late and muddy and half built. So were the English, at first."),
            // ---- May 1907 --------------------------------------------------------------------------------------
            E("pinkstar", 1907, 5, 7, "west", 1, "sport", "PINK STAR WINS THE DERBY",
              "Pink Star, at fifteen to one, took the Kentucky Derby in the mud from a field nobody had picked him in.",
              "Pink Star won the Derby at fifteen to one, in the mud. The fellow at the saloon had two dollars on him.",
              "Derby's run. A long shot in the mud. The favorites finished behind a horse named like a dance hall girl."),
            E("sfstreetcars", 1907, 5, 8, "west", 2, "crime", "SHOOTING IN THE SAN FRANCISCO CAR STRIKE",
              "The streetcar men are on strike in San Francisco and the company runs the cars with gunmen aboard, who fired into the crowd on the second day.",
              "The Frisco car strike. The company put men with rifles on the cars and they shot into the crowd. Two dead.",
              "They're fighting the car strike with hired guns in San Francisco. A year after the quake, shooting itself."),
            E("haywoodtrial", 1907, 5, 10, "high", 3, "law", "HAYWOOD ON TRIAL AT BOISE",
              "Big Bill Haywood of the Western Federation of Miners is on trial at Boise for the dynamite murder of Governor Steunenberg, with Darrow for the defense.",
              "The Haywood trial's started at Boise. For blowing up the governor at his gate. Darrow's defending him.",
              "Haywood, the one-eyed miners' man, is on trial at Boise. Roosevelt called him undesirable before the jury sat.",
              "Every union man up here has a dollar in the Haywood fund, and every mine owner ten on the other side."),
            // ---- June 1907 -------------------------------------------------------------------------------------
            E("orchard", 1907, 6, 6, "high", 2, "crime", "ORCHARD CONFESSES TO THE STEUNENBERG BOMB",
              "Harry Orchard, the state's witness at Boise, told the court he killed Governor Steunenberg with a bomb at his gate on the federation's orders, and confessed a dozen more.",
              "Orchard on the stand at Boise. Says he set the bomb that killed the governor, on the union's word. So he says.",
              "That Orchard. More killings than the Ketchum gang, and the state's witness. The jury eyes him like a snake."),
            E("pekingparis", 1907, 6, 12, "world", 1, "wonder", "MOTORCARS TO RACE FROM PEKING TO PARIS",
              "Five motorcars have set out from Peking to drive to Paris across Mongolia and Siberia, where there is no road at all, for a Paris newspaper's prize.",
              "Motorcars driving from Peking to Paris, across a desert with no road. Can't get one to the next county.",
              "Five motorcars left Peking for Paris. Camels carry the gasoline ahead of them. The paper calls it sport."),
            E("hague07", 1907, 6, 16, "world", 1, "world", "THE SECOND PEACE CONFERENCE",
              "The nations have met again at The Hague to talk of peace, forty-four of them this time, while every one of them builds battleships.",
              "They're at The Hague again talking peace. Forty-four countries, every one laying down a battleship.",
              "The second peace conference. More rules for war. Nobody's proposing fewer wars."),
            E("twainoxford", 1907, 6, 27, "world", 1, "life", "MARK TWAIN MADE A DOCTOR AT OXFORD",
              "Oxford University gave Mark Twain a doctor's degree in a scarlet gown, and he says he will wear the gown to everything for the rest of his life.",
              "Oxford made Mark Twain a doctor, in a red gown. He says he'll wear it to the grave and in it. I believe him.",
              "Mark Twain's a doctor of letters now, in England. The old river pilot from Hannibal. In a scarlet gown."),
            // ---- July 1907 -------------------------------------------------------------------------------------
            E("follies", 1907, 7, 9, null, 1, "life", "THE FOLLIES ON A NEW YORK ROOF",
              "A showman named Ziegfeld has put fifty girls and a comic revue on a roof garden in New York and calls it the Follies of 1907.",
              "There's a show on a New York roof with fifty girls. The Follies. Not much to the costumes or the plot.",
              "Follies of 1907, girls on a roof garden. I've no business in New York and never had, more's the pity."),
            E("oklahomaconstitution", 1907, 7, 17, "west", 1, "politics", "OKLAHOMA SIGNS ITS CONSTITUTION",
              "The convention at Guthrie has signed the longest constitution any state ever wrote, with the initiative and the referendum and a ban on every trust it could think of.",
              "The Oklahoma constitution's signed. Longest ever written. Everything a Populist ever asked for in one book.",
              "Oklahoma's constitution reins in the railroads, trusts and banks and bans the saloon. Roosevelt says unfit."),
            E("haywoodacquitted", 1907, 7, 29, "high", 3, "law", "HAYWOOD NOT GUILTY",
              "The Boise jury found Haywood not guilty, believing nothing Orchard said without a second witness, and the mining camps rang their bells.",
              "Haywood's acquitted. The jury wouldn't hang a man on Orchard's word. The camps rang every church bell.",
              "Not guilty at Boise. Darrow talked eleven hours. The miners say justice. The paper says the jury was afraid.",
              "The Haywood jury let him go. Orchard's in the pen and the governor's still dead. Nothing's settled but that."),
            // ---- August 1907 -----------------------------------------------------------------------------------
            E("walterjohnson", 1907, 8, 3, "west", 1, "sport", "A BOY FROM IDAHO PITCHES FOR WASHINGTON",
              "A nineteen-year-old named Johnson from the Idaho bush leagues pitched his first game for Washington, and the Detroit men say they never saw the ball.",
              "Washington's got a pitcher out of the Idaho leagues, Johnson, nineteen. Throws so hard the catcher winces.",
              "A boy from the Snake River country's pitching in the big league. Detroit says they never saw the ball."),
            E("standardoilfine", 1907, 8, 4, null, 3, "money", "STANDARD OIL FINED TWENTY-NINE MILLIONS",
              "Judge Landis at Chicago has fined the Standard Oil Company twenty-nine million dollars for taking secret rebates from the railroads.",
              "They fined Standard Oil twenty-nine million dollars for rebates. Rockefeller will pay it when pigs fly.",
              "Twenty-nine millions, a Chicago judge said. Rockefeller was at golf when they told him. Finished the round.",
              "The biggest fine in history on the biggest company in history. It'll never be paid. Everybody knows it."),
            E("georgiadry", 1907, 8, 8, "south", 1, "law", "GEORGIA GOES DRY",
              "Georgia has voted itself dry from the new year, the first Southern state to shut every saloon, and Alabama is talking of following.",
              "Georgia's gone dry. Every saloon in the state shut by law come New Year's. The whiskey men are off to Florida.",
              "Georgia voted out the saloon, the whole state. The Baptists did it. Alabama next, and then this way."),
            E("borghese", 1907, 8, 12, "world", 1, "wonder", "THE ITALIAN PRINCE REACHES PARIS",
              "Prince Borghese's motorcar has reached Paris from Peking in sixty days, across Mongolia and Siberia, three weeks ahead of the next.",
              "That Italian prince drove from China to Paris in sixty days, across Siberia in a motorcar. Nobody shot him.",
              "The Peking to Paris race is won. Sixty days through country with no roads. The horse is in trouble."),
            E("sfplague", 1907, 8, 20, "west", 1, "disaster", "THE PLAGUE AGAIN IN SAN FRANCISCO",
              "The plague is back in San Francisco among the rats of the ruins, and the city pays a bounty on rats and hopes the rest of the country does not notice.",
              "Plague in Frisco again, in the rats in the rubble. The city pays a bounty on rats by the tail.",
              "The plague's back on the coast. The paper says it's the rats. It said that was nothing, the last time."),
            E("quebecbridge", 1907, 8, 30, "world", 2, "disaster", "THE GREAT QUEBEC BRIDGE FALLS",
              "The great bridge building across the St. Lawrence at Quebec has fallen into the river with the men on it, and seventy-five are dead.",
              "The Quebec bridge fell into the river with the workmen on it. Seventy-five dead. Biggest bridge in the world.",
              "That bridge in Canada went down, all steel. The engineers said it was the strongest ever built."),
            // ---- September 1907 --------------------------------------------------------------------------------
            E("naturefakers", 1907, 9, 10, null, 1, "life", "THE PRESIDENT AGAINST THE NATURE FAKERS",
              "The President has written in a magazine against the nature writers whose wolves teach their cubs and whose birds set broken legs, and calls them fakers.",
              "Roosevelt's fighting the nature writers now. Says their wolves and foxes are fairy tales. The President!",
              "Nature fakers, Teddy calls them. He's read every one of those books, it seems, and shot every animal in them."),
            E("lusitania", 1907, 9, 14, "world", 2, "wonder", "THE BIGGEST SHIP IN THE WORLD AT NEW YORK",
              "The Cunarder Lusitania has come into New York on her first crossing, the largest and fastest ship ever built, with four funnels and a town's worth of people aboard.",
              "The Lusitania's in New York. Biggest ship ever built. Seven hundred and ninety feet. Carries two thousand.",
              "A ship as long as three blocks, with four smokestacks. The Lusitania crossed the ocean in five days."),
            E("oklahomavote", 1907, 9, 18, "west", 2, "politics", "OKLAHOMA VOTES FOR STATEHOOD, AND AGAINST THE SALOON",
              "The people of the two territories voted their constitution through by two to one, and voted the whole new state dry at the same election.",
              "Oklahoma voted for the constitution and voted itself dry in one day. A state born without a saloon.",
              "They've made Oklahoma dry before it's even a state. The whiskey's going out by the wagonload before November."),
            // ---- October 1907 ----------------------------------------------------------------------------------
            E("taxicabs", 1907, 10, 2, null, 1, "wonder", "TAXICABS ON THE STREETS OF NEW YORK",
              "Sixty-five gasoline cabs with a meter on the dash have begun running in New York, the fare reckoned by the mile by the machine.",
              "New York's motor cabs have a clock that counts the fare. A taximeter. Argue with the clock, not the driver.",
              "Cabs with meters in New York. The horse cabmen are throwing stones at them. I'd throw stones too."),
            E("plaza", 1907, 10, 2, null, 1, "life", "THE PLAZA HOTEL OPENS ON FIFTH AVENUE",
              "The new Plaza Hotel by the park has opened with rooms at two dollars and fifty cents and suites the millionaires have taken by the year.",
              "A new hotel in New York, the Plaza, where the rich live by the year. Two and a half dollars, the cheapest bed.",
              "The Plaza's marble from sidewalk to roof. The Vanderbilts were in the first night. I'd not get past the door."),
            E("cubswin", 1907, 10, 13, null, 2, "sport", "THE CUBS SWEEP DETROIT",
              "The Chicago Cubs beat Detroit four games straight for the championship of the world, after a tie in the first, and Cobb could not hit them.",
              "The Cubs took Detroit four straight. Cobb never got going. Chicago's champion of the world and won't shut up.",
              "World's series is over, Chicago four to nothing after a tie. The best club ever seen, says Chicago."),
            E("merrywidow", 1907, 10, 22, null, 1, "life", "THE MERRY WIDOW AND HER HAT",
              "The Merry Widow, the Vienna operetta, has opened in New York, and its waltz is on every hand organ and its great hat on every woman who can afford one.",
              "The Merry Widow waltz is on every hand organ. My wife wants a hat a yard across, like the Vienna actress.",
              "A Vienna show's got every woman in a hat as big as a wagon wheel. The men can't see past them in church."),
            E("knickerbocker", 1907, 10, 23, null, 3, "money", "THE KNICKERBOCKER TRUST SHUTS ITS DOORS",
              "The Knickerbocker Trust Company of New York stopped paying after a run of eight million dollars in three hours, and the lines are forming at every bank in the city.",
              "The Knickerbocker Trust shut its doors in New York, eight million gone in a morning. Lines at every bank now.",
              "A panic in New York. The paper says the other banks are sound. The paper said that in '93.",
              "Bank run in New York, lines round the block. Morgan's called the bankers to his library like a schoolmaster."),
            E("westernbankholiday", 1907, 10, 28, "west", 3, "money", "THE WESTERN GOVERNORS DECLARE BANK HOLIDAYS",
              "The governors of Nevada, California, Oregon and Washington have declared legal holidays day after day to keep the banks shut, and the towns pay in scrip.",
              "The governor's declared a holiday so the banks can stay shut. Every day's a holiday till New York pays up.",
              "Banks shut by the governor's order. The store takes scrip, and nobody's seen a gold piece in a week.",
              "The bank's been on holiday nine days. The sheriff guards the door against the depositors."),
            // ---- November 1907 ---------------------------------------------------------------------------------
            E("emmettdalton", 1907, 11, 4, "west", 1, "west", "EMMETT DALTON LET OUT OF PRISON",
              "Emmett Dalton, the one of the Dalton boys who lived through the Coffeyville raid, has been let out of the Kansas penitentiary after fourteen years.",
              "Emmett Dalton's out of prison, the last of the Coffeyville raiders. Fourteen years in the Kansas pen.",
              "They let Emmett Dalton go. His brothers died in the street at Coffeyville. He says he'll go straight."),
            E("morganrescue", 1907, 11, 5, null, 2, "money", "MORGAN'S BANKERS HOLD THE LINE",
              "Mr. Morgan locked the bankers in his library till they pledged twenty-five millions, and the President let the steel trust buy the Tennessee company to stop the fall.",
              "Morgan saved the market, the paper says. Locked the bankers in his library all night till they paid up.",
              "The steel trust bought the Tennessee company with Roosevelt's blessing. The trust grew. The panic didn't stop."),
            E("scrip", 1907, 11, 6, null, 3, "money", "THE COUNTRY PAYS IN SCRIP",
              "Clearing-house certificates and the companies' own scrip pass for money in every city, cash is hoarded, and the banks pay out a few dollars a day and no more.",
              "The mine's paying in scrip, paper with the company's name on it. The store takes it at ninety cents.",
              "The bank pays out ten dollars a day and no more. The payroll came in certificates. We're back to barter.",
              "Nobody's seen gold in a month. The paper says it's all in Europe or under mattresses. Mine's in neither."),
            E("oklahomastate", 1907, 11, 17, "west", 3, "west", "OKLAHOMA THE FORTY-SIXTH STATE",
              "The President signed the proclamation and Oklahoma is a state, the Indian Territory and all, with a mock wedding of a cowboy and an Indian girl at Guthrie to mark it.",
              "Oklahoma's a state. Forty-six now. At Guthrie they married a cowboy to an Indian girl to show the two joining.",
              "The Indian Territory's gone, Oklahoma's a state as of today. The Cherokee council met for the last time.",
              "Forty-six stars on the flag come summer. Oklahoma. A state made of the Indians' land, and dry by its own vote."),
            E("mauretania", 1907, 11, 17, "world", 1, "wonder", "THE LUSITANIA'S SISTER SAILS",
              "The Mauretania, sister to the Lusitania and a little longer, has sailed on her first crossing to take the record from her.",
              "Another ship bigger than the last, the Mauretania. The English build them in pairs now, like boots.",
              "The Lusitania's sister's sailed, the Mauretania. Five days to England. My grandfather took seven weeks."),
            // ---- December 1907 ---------------------------------------------------------------------------------
            E("goldfieldtroops", 1907, 12, 7, "high", 2, "law", "FEDERAL TROOPS SENT TO GOLDFIELD",
              "The President has sent regular troops to Goldfield, Nevada, where the mine owners shut out the union and asked for soldiers before a shot was fired.",
              "Soldiers in Goldfield. The owners asked Roosevelt for troops against the union and he sent them before a shot.",
              "Federal troops at Goldfield for the mine owners, the richest camp in Nevada. The union calls it a put-up job."),
            E("monongah", 1907, 12, 8, null, 3, "disaster", "THREE HUNDRED AND SIXTY DEAD AT MONONGAH",
              "An explosion in the Monongah mines of West Virginia has killed the men in two shafts, above three hundred and sixty, the worst day in the history of American coal.",
              "Three hundred and sixty miners killed in one blast at Monongah, West Virginia. Two mines at once.",
              "The worst mine disaster there's ever been, Monongah. They're still bringing them up. A town with no men left.",
              "Three hundred and sixty at Monongah. Think of the widows at one church. No miner in the mountains slept."),
            E("kiplingnobel", 1907, 12, 11, "world", 1, "life", "KIPLING WINS THE NOBEL PRIZE",
              "Rudyard Kipling has the Nobel Prize for literature, the first Englishman to have it, and near forty thousand dollars with it.",
              "Kipling won the prize in Sweden. Forty thousand dollars for poetry. I was in the wrong line of work.",
              "The Swedes gave Kipling their big prize. The barrack-room poet. The one who told us the islands were a burden."),
            E("rooseveltnorun", 1907, 12, 12, null, 2, "politics", "ROOSEVELT SAYS AGAIN HE WILL NOT RUN",
              "The President has put out a statement that he meant what he said in 1904 and will not be a candidate again, and names nobody, and everybody names Taft.",
              "Roosevelt says he won't run again. Said it in '04 and twice since. Every time he says it, Taft gets fatter.",
              "Teddy's not running, he says, in writing. Half the country don't believe him. The rest wear Taft buttons."),
            E("whitefleet", 1907, 12, 17, null, 3, "world", "THE FLEET SAILS ROUND THE WORLD",
              "Sixteen battleships painted white have steamed out of Hampton Roads past the President's yacht to go round the world, the greatest fleet ever sent on a cruise.",
              "The fleet sailed, sixteen battleships white as a wedding. Round the whole world, by way of Japan.",
              "Sixteen battleships going round the world to show the flag. The Japanese will see them. That's the point.",
              "The white fleet's off, fourteen thousand sailors. My nephew's on the Connecticut. He'll see the whole world."),
            E("darrmine", 1907, 12, 20, null, 2, "disaster", "TWO HUNDRED AND THIRTY-NINE MORE AT THE DARR MINE",
              "Two weeks after Monongah the Darr mine in Pennsylvania has blown up and killed two hundred and thirty-nine, and Washington talks at last of a bureau of mines.",
              "Another mine gone, the Darr, in Pennsylvania. Two hundred and thirty-nine. Two weeks after Monongah.",
              "Six hundred coal miners dead in a month. The owners blame the gas. The miners blame the owners.")
        };

        private static readonly AlmanacEvent[] Everyday1907 =
        {
            E("motorcarprice", 1907, 0, 0, null, 2, "wonder", "A MOTORCAR FOR SIX HUNDRED DOLLARS",
              "Mr. Ford's runabout and the Oldsmobile sell for six hundred dollars and run on any road, and there are a hundred and forty thousand motorcars in the country.",
              "A Ford runabout for six hundred dollars. The doctor's got one. Twenty minutes to a call, an hour under it.",
              "A hundred and forty thousand motorcars in the country now. One came through Tuesday and killed a hen."),
            E("nickelodeon", 1907, 0, 0, null, 2, "life", "THE NICKEL THEATERS",
              "Every town with a vacant store has a nickelodeon now, moving pictures for five cents from noon to midnight, and the preachers say it is the ruin of the young.",
              "There's a nickelodeon in the old harness shop. Moving pictures for five cents. The children would live in it.",
              "Moving pictures for a nickel. My boy's seen the same train robbery eleven times and knows the horses' names."),
            E("partyline", 1907, 0, 0, "west", 1, "life", "THE TELEPHONE ON THE PARTY LINE",
              "The farm telephone companies string wire on fence posts and twelve families share a line, and every one of them listens when the bell rings for the others.",
              "We're on the party line now with twelve families. Mrs. Pike picks up every call. We just include her.",
              "Telephone on the fence wire out to the ranch. Two longs and a short is us. The valley hears the doctor called."),
            E("grazingfees", 1907, 0, 0, "west", 2, "west", "THE RANGERS AND THE GRAZING FEE",
              "The forest rangers count the cattle on the reserves now and the stockmen pay by the head to graze land their fathers ran free, and the meetings at every county seat are loud.",
              "A ranger counted my steers on the reserve and sent a bill. Twenty cents a head for grass God grew.",
              "Grazing fees on the forest. Pay the government to run cattle where you always ran them. Washington's way."),
            E("reclamation", 1907, 0, 0, "west", 1, "west", "THE GOVERNMENT DAMS",
              "The Reclamation Service is building dams in Arizona, Nevada and Idaho to water deserts, and sells the farms under them to anybody who will settle.",
              "The government's damming rivers to water the desert. Forty-acre farms under the ditch, on time payments.",
              "Reclamation, they call it. A dam, a farm under it, and a water bill with it. Beats a dry quarter section."),
            E("goldfieldboom", 1907, 0, 0, "high", 2, "money", "GOLDFIELD, THE LAST OF THE BOOM CAMPS",
              "Goldfield, Nevada, has twenty thousand people where there was sagebrush four years ago, and its stock is sold on every curb from Reno to New York.",
              "Goldfield's got twenty thousand people and rich ore. Four years ago it was a jackrabbit's claim.",
              "They sell Goldfield shares on the street corners. Every clerk owns a mine in Nevada. Most will own a hole."),
            E("butchgone", 1907, 0, 0, "west", 1, "west", "THE WILD BUNCH SCATTERED",
              "The old Wild Bunch is dead or gone, Curry dead in Colorado, Cassidy and Longabaugh somewhere in South America, and the Hole-in-the-Wall holds nothing but sheep.",
              "Butch Cassidy's in South America, they say. Or dead. The Hole-in-the-Wall's full of sheep now.",
              "The last train robbers are in the Argentine or the ground. Nobody's held up the Overland in years."),
            E("airship", 1907, 0, 0, null, 1, "wonder", "THE FLYING MACHINES",
              "The Wright brothers of Ohio say they have flown twenty-four miles in a machine and will show nobody; the French fly in public for a minute and are famous.",
              "The Wright brothers say they flew twenty miles and won't let anybody see. The French fly a minute in public.",
              "Flying machines. A Frenchman stayed up a whole minute, the paper says. My rooster does better off the barn."),
            E("wirelessships", 1907, 0, 0, null, 1, "wonder", "THE WIRELESS ON THE LINERS",
              "Every big liner carries a wireless operator now, and passengers send telegrams from the middle of the ocean and read the day's news at sea.",
              "The big liners print a newspaper in the middle of the ocean now, by wireless. No getting away from the news.",
              "Wireless on every big ship. A man can wire his wife from mid-ocean to say he's seasick. Progress."),
            E("postcards", 1907, 0, 0, null, 1, "life", "THE POSTCARD CRAZE",
              "The country mails picture postcards by the hundred million, the depot or the courthouse with a line on the back, and the drugstore racks turn like windmills.",
              "Everybody's sending picture postcards. The depot, the courthouse, the new bank. My wife keeps an album.",
              "Our depot's on a picture postcard now. It looks better on the card. Most things do."),
            E("teddybear", 1907, 0, 0, null, 1, "life", "THE TEDDY BEAR",
              "The stuffed bear named for the President after he spared one on a hunt is in every nursery and in the arms of grown women on the trains.",
              "Every child's got a teddy bear, named for Roosevelt because he wouldn't shoot a tied bear. Good for votes.",
              "A stuffed bear with the President's name. I saw a grown woman carrying one on the cars. A bear named Teddy."),
            E("muckrakers", 1907, 0, 0, null, 1, "politics", "THE MAGAZINES AND THE MUCK RAKE",
              "The ten-cent magazines run a scandal a month, the beef trust, the insurance men, the Senate, and the President calls the writers muckrakers and reads every word.",
              "Every magazine's got an exposure in it. The beef trust, the Senate, the railroads. Muckrakers, Teddy says.",
              "McClure's has the Standard Oil story again. Ten cents a month to find out who owns you."),
            E("harrimaninquiry", 1907, 0, 0, null, 1, "money", "HARRIMAN BEFORE THE COMMISSION",
              "The Interstate Commerce Commission has had Mr. Harriman on the stand about how he bought his railroads, and he told them it was none of their business in politer words.",
              "Harriman told the railroad commission to mind its own affairs. He owns the affairs.",
              "Harriman was asked how he got the Southern Pacific. Said he bought it. Asked with what. Said with money."),
            E("twocentfare", 1907, 0, 0, null, 1, "law", "TWO CENTS A MILE",
              "A dozen legislatures have cut the railroad fare to two cents a mile by law this year, and the railroads say they will take it to the courts and the courts will give it back.",
              "The state cut the railroad fare to two cents a mile. Two cents till the judge says three.",
              "Two-cent fare law. First law in years that cost the railroad and not me. It'll last till the appeal."),
            E("cottongood", 1907, 0, 0, "south", 1, "money", "COTTON AT ELEVEN CENTS",
              "Cotton has brought eleven cents and better this year, and the planter who hung on through the six-cent years is paying the store for once.",
              "Eleven cents for cotton. Eleven. Not long ago it was six, and we ate corn meal. The store's getting paid.",
              "Cotton's dear this year. The gin runs nights. Every mule in the parish is worth a hundred dollars."),
            E("weevilhere", 1907, 0, 0, "south", 2, "disaster", "THE WEEVIL IN THE LOUISIANA COTTON",
              "The boll weevil has crossed the Sabine and is in the Louisiana cotton now, and the agricultural men say plant early, plant less, and burn the stalks.",
              "The boll weevil's in the parish. Found them in the lower field. Burn the stalks, the government man says.",
              "Boll weevil's here at last, eight years crossing Texas. The planters are talking rice and cattle, and praying."),
            E("mosquito", 1907, 0, 0, "south", 1, "wonder", "THE MOSQUITO PROVED THE CARRIER OF THE FEVER",
              "New Orleans has had no yellow fever since the mosquito campaign of 1905, and the city screens its cisterns and oils its gutters and believes the doctors at last.",
              "No yellow fever two summers now. It was the mosquito. Screen the cistern and oil the gutter.",
              "Yellow fever's gone from New Orleans since they went after the mosquitoes. A bug the size of a hair."),
            E("panamadig", 1907, 0, 0, null, 2, "wonder", "THE BIG DITCH AT PANAMA",
              "The army engineers have the Panama Canal now, with forty thousand men digging and the fever beaten, and the President went down himself to sit on a steam shovel.",
              "They're digging the canal at Panama. Roosevelt went down and sat on a steam shovel for the photographers.",
              "The Panama ditch. The French died by the thousand trying it. Our doctors killed the mosquitoes first."),
            E("cowboypictures", 1907, 0, 0, "west", 1, "life", "COWBOYS IN THE MOVING PICTURES",
              "The moving picture companies make cowboy pictures in Colorado and New Jersey, and real cowhands ride in them for three dollars a day and a laugh at the costumes.",
              "They're making moving pictures of cowboys, real hands at three dollars a day. The director can't sit a horse.",
              "Cowboy pictures at the nickelodeon. Made in New Jersey, half of them. The horses are real; nothing else is."),
            E("mailorderhouse", 1907, 0, 0, null, 1, "life", "SEARS SELLS EVERYTHING BUT THE HOUSE, AND SOON THE HOUSE",
              "Sears, Roebuck ships a railroad car of goods every few minutes from Chicago, and the storekeepers' associations beg the farmers to buy at home.",
              "The Sears book's bigger than the Bible this year. The storekeepers print pamphlets begging us to buy at home.",
              "Everything from Chicago by mail. Guns, stoves, pianos. The store's down to tobacco and credit."),
            E("caruso", 1907, 0, 0, null, 1, "life", "CARUSO ON THE PHONOGRAPH",
              "The Italian tenor Caruso sings at the Metropolitan for two thousand dollars a night and on the phonograph for anyone with a machine, and the records sell by the million.",
              "Caruso on the phonograph. The barber's got one. An Italian singing in a horn, and the whole shop goes quiet.",
              "The great tenor Caruso on a wax disc. My wife plays it Sundays. I've grown fond of him. Don't tell the saloon."),
            E("chautauqua", 1907, 0, 0, "west", 1, "life", "THE CHAUTAUQUA TENT",
              "The traveling Chautauqua pitches its tent in every town of the plains for a week of lectures, bands and Bryan, and the farmers come in by the hundred wagons.",
              "Chautauqua's coming. A week in the tent. Lectures, a band, and Bryan if we're lucky. Same speech every year.",
              "The Chautauqua tent's up on the fairground. Culture for a dollar a week. The young folks go for the courting."),
            E("schooldays", 1907, 0, 0, null, 1, "life", "SCHOOL DAYS, THE SONG",
              "School Days, with its golden rule days and its slate, is sung in every parlor, and Mr. Cohan's Harrigan is whistled by every Irishman on the street.",
              "School days, school days, dear old golden rule days. My daughter sings it till I could break the slate.",
              "Harrigan, that's me. Every Irishman in town sings Cohan's song, and half the Germans."),
            E("japanscare", 1907, 0, 0, "west", 1, "politics", "THE TALK OF WAR WITH JAPAN",
              "The papers on the coast talk of war with Japan every week, over the schools and the laborers, and the Japanese papers talk of it back.",
              "The coast papers talk of war with Japan, over schoolchildren. Japan beat Russia. They'd not be Spain.",
              "War talk with Japan again, Hearst's papers mostly. Sending the fleet round is how a man acts when he's afraid."),
            E("motorcycle", 1907, 0, 0, null, 1, "life", "THE MOTORCYCLE",
              "The motorcycle, a light machine with a gasoline engine between its wheels, is sold for two hundred dollars and frightens horses worse than the motorcar.",
              "A fellow came through on a motorcycle. Two hundred dollars. Louder than a threshing machine, and proud of it.",
              "Motorcycles now. The horses hate them worse than the motorcars. So do I."),
            E("devilstower", 1907, 0, 0, "west", 1, "west", "THE NATIONAL MONUMENTS",
              "The President has made the Devil's Tower in Wyoming and the Petrified Forest in Arizona national monuments under his new law, and the Grand Canyon is said to be next.",
              "Roosevelt's made the Devil's Tower a national monument. The government owns a rock now and you can't chip it.",
              "National monuments, the Devil's Tower and the Petrified Forest. The President's fencing in the scenery."),
            E("oldwestgone07", 1907, 0, 0, "west", 1, "west", "THE OLD WEST IN THE SHOW RING",
              "Buffalo Bill and Pawnee Bill and the 101 Ranch show the old West in tents to people who never saw it, and the men who lived it sit in the stands and say it was never like that.",
              "Three Wild West shows on the road, Cody's, Pawnee Bill's and the 101. The West's a show in a tent in Ohio.",
              "Went to the Wild West show. The old fellow beside me said it was never like that. He'd know. He wasn't there."),
            E("adding", 1907, 0, 0, null, 1, "wonder", "THE ADDING MACHINE AND THE CASH REGISTER",
              "Every bank has an adding machine and every store a cash register that rings, and the clerk who could add a column in his head is out of work.",
              "The store's got a cash register that rings. The clerk used to add in his head. Now he pulls a handle.",
              "Adding machines at the bank. Turn the crank and the sum comes out. The bookkeeper says it's never wrong."),
            E("eighthourtalk", 1907, 0, 0, null, 1, "law", "THE EIGHT-HOUR DAY",
              "The unions ask eight hours in every trade and have it in a few, and the mine owners and the mills say the country would starve on eight.",
              "Eight hours. The miners have it in some camps. The owners say the country can't afford it. It affords Morgan.",
              "Signed the eight-hour petition. Worked twelve for thirty years. I'd like to see what the other four look like.")
        };
    }
}
